<?php
namespace qqworld_collector\module\collect_item; use qqworld_collector\lib; class taxonomy extends lib { var $guid; public function init() { add_filter( 'qqworld-collector-collecting-engine-collect-item-' . $this->guid, array($this, 'filter'), 10, 7 ); add_filter( 'qqworld-collector-collecting-engine-collect-item-after-filter-' . $this->guid, array($this, 'filter_after'), 10, 6 ); } public function filter($items, $args, $source_link, $html, $download_args, $settings, $mode) { return $items; } public function filter_after($items, $args, $source_link, $html, $settings, $mode) { $limit = isset($args['limit']) ? $args['limit'] : '2-'; $limit2 = isset($args['limit2']) ? $args['limit2'] : '5'; $disallow_pure_english_numbers = isset($args['disallow-pure-english-numbers']) ? filter_var($args['disallow-pure-english-numbers'], FILTER_VALIDATE_BOOLEAN) : 1; if ($this->is_not_empty($items)) { foreach ($items as $i => &$item) { if (is_array($item)) { foreach ($item as $it) { $items[] = $it; } unset($items[$i]); } else { $item = $item; } } if ($limit2) $items = array_slice($items, 0, $limit2); $limit = explode('-', $limit); foreach ($items as $index => &$item) { $item = trim(strip_tags($item)); if ( $disallow_pure_english_numbers && preg_match('/^\w*$/i', $item) ) { unset($items[$index]); continue; } if (count($limit) > 1) { if ( ($limit[0] && mb_strlen(strip_tags($item)) < $limit[0]) || ($limit[1] && mb_strlen(strip_tags($item)) > $limit[1]) ) { unset($items[$index]); continue; } } else { if ( mb_strlen(strip_tags($item)) > $limit[0] ) { unset($items[$index]); continue; } } } $items = array_filter($items); $items = array_values($items); } return $items; } } ?>